// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 amount, address caller, uint256 depositAmount, address depositor) public {
        vm.assume(amount > 0);
        vm.assume(depositAmount > 0);
        vm.assume(caller != address(0) && caller != address(c));
        vm.assume(depositor != address(0) && depositor != address(c));

        vm.deal(caller, amount);
        vm.prank(caller);
        c.addToBalance{value: amount}();

        vm.prank(caller);
        (bool withdrawOk, ) = address(c).call(abi.encodeWithSelector(c.withdrawBalance.selector));
        require(withdrawOk, "Withdrawal must succeed for EOA");

        vm.deal(depositor, depositAmount);
        vm.prank(depositor);
        (bool depositOk, ) = address(c).call{value: depositAmount}(abi.encodeWithSelector(c.addToBalance.selector));

        assertTrue(depositOk);
    }
}
